 void startClock(){handler.post(new Runnable(){public void run(){Date d=new Date();clock.setText(new SimpleDateFormat("HH:mm:ss",new Locale("pt","BR")).format(d));date.setText(new SimpleDateFormat("EEE, dd 'de' MMM 'de' yyyy",new Locale("pt","BR")).format(d));handler.postDelayed(this,1000);}});}
 String abs(String u){if(u==null||u.trim().length()==0)return "";u=u.trim();if(u.startsWith("http://")||u.startsWith("https://"))return u;return BuildConfig.API_BASE_URL.replaceAll("/$","")+"/"+u.replaceFirst("^/","");}
 byte[] getBytes(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(true);c.setRequestProperty("Accept","image/*,*/*");try{if(c.getResponseCode()<200||c.getResponseCode()>299)throw new IOException("HTTP "+c.getResponseCode());ByteArrayOutputStream o=new ByteArrayOutputStream();InputStream in=c.getInputStream();byte[] b=new byte[16384];int n;while((n=in.read(b))>0)o.write(b,0,n);in.close();return o.toByteArray();}finally{c.disconnect();}}
 Bitmap decode(byte[] data){try{BitmapFactory.Options o=new BitmapFactory.Options();o.inPreferredConfig=Bitmap.Config.RGB_565;o.inDither=true;return BitmapFactory.decodeByteArray(data,0,data.length,o);}catch(Exception e){return null;}}
 void saveCache(String name,byte[] data){try{FileOutputStream f=openFileOutput(name,MODE_PRIVATE);f.write(data);f.close();}catch(Exception e){}}
 Bitmap loadCache(String name){try{FileInputStream f=openFileInput(name);BitmapFactory.Options o=new BitmapFactory.Options();o.inPreferredConfig=Bitmap.Config.RGB_565;o.inDither=true;Bitmap b=BitmapFactory.decodeStream(f,null,o);f.close();return b;}catch(Exception e){return null;}}
 void loadCachedTheme(){Bitmap w=loadCache("panel_wallpaper.img");if(w!=null)bgView.setRemote(w);Bitmap b=loadCache("panel_banner.img");if(b!=null&&remoteBanner!=null){remoteBanner.setImageBitmap(b);remoteBanner.setVisibility(View.VISIBLE);}}
 void loadRemoteTheme(){new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(BuildConfig.API_BASE_URL+"/api/launcher-v4/theme").openConnection();c.setConnectTimeout(8000);c.setReadTimeout(8000);c.setRequestProperty("Accept","application/json");String text;try{if(c.getResponseCode()!=200)return;BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder s=new StringBuilder();String line;while((line=r.readLine())!=null)s.append(line);r.close();text=s.toString();}finally{c.disconnect();}JSONObject j=new JSONObject(text);String wu=abs(j.optString("wallpaper_url",""));String bu=abs(j.optString("banner_url",""));final Bitmap[] wb={null};final Bitmap[] bb={null};if(wu.length()>0){byte[] d=getBytes(wu);saveCache("panel_wallpaper.img",d);wb[0]=decode(d);}if(bu.length()>0){byte[] d=getBytes(bu);saveCache("panel_banner.img",d);bb[0]=decode(d);}runOnUiThread(()->{if(wb[0]!=null)bgView.setRemote(wb[0]);if(remoteBanner!=null){if(bb[0]!=null){remoteBanner.setImageBitmap(bb[0]);remoteBanner.setVisibility(View.VISIBLE);}else if(bu.length()==0)remoteBanner.setVisibility(View.GONE);}});}catch(Exception e){}finally{handler.postDelayed(()->loadRemoteTheme(),60000);}}).start();}
 class BgView extends View{Paint p=new Paint(3);Bitmap remote;public BgView(Context c){super(c);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}void setRemote(Bitmap b){remote=b;invalidate();}protected void onDraw(Canvas c){super.onDraw(c);int w=getWidth(),h=getHeight();LinearGradient g=new LinearGradient(0,0,w,h,new int[]{Color.rgb(2,4,15),Color.rgb(8,15,55),Color.rgb(35,3,12),Color.BLACK},null,Shader.TileMode.CLAMP);p.setShader(g);c.drawRect(0,0,w,h,p);p.setShader(null);if(remote!=null&&!remote.isRecycled()){float s=Math.max(w/(float)remote.getWidth(),h/(float)remote.getHeight());int dw=Math.round(remote.getWidth()*s),dh=Math.round(remote.getHeight()*s),l=(w-dw)/2,t=(h-dh)/2;Rect dst=new Rect(l,t,l+dw,t+dh);p.setFilterBitmap(true);p.setDither(true);c.drawBitmap(remote,null,dst,p);return;}p.setStrokeWidth(Math.max(2,h/300));for(int i=0;i<10;i++){p.setColor(Color.argb(70,15,80+i*12,255));c.drawLine(0,i*h/10,w,(i*h/10)+h/7,p);}for(int i=0;i<7;i++){p.setColor(Color.argb(80,255,30+i*15,10));c.drawLine(w,i*h/7,0,(i*h/7)+h/4,p);}RadialGradient r=new RadialGradient(w/2,h/2,Math.max(w,h)/2,new int[]{Color.argb(105,255,70,0),Color.TRANSPARENT},null,Shader.TileMode.CLAMP);p.setShader(r);c.drawRect(0,0,w,h,p);p.setShader(null);}}
